R1_classify_alert.text:
{
  "title": "硫化溫度異常",
  "summary": "CURE-07溫度驟降至122°C，已硫化10h/28h，需檢視蒸汽管線H2與溫控邏輯"
}

R2_plan.text:
{
  "goal": "判定是感測器漂移還是真實溫度下降，並決定是延長硫化還是重排。",
  "hypothesis": {
    "id": "sensor_drift",
    "statement": "同管線 6 號、8 號溫度正常，僅 7 號下降，指向感測器漂移或單機洩漏。",
    "cause_code": "SOP-SN-01 cross-check"
  },
  "steps": [
    {
      "id": "S1",
      "tool": "read_sensors",
      "args": {"machine_id": "CURE-07", "sensor": "steam_kgf_cm2"},
      "purpose": "確認蒸汽壓趨勢。"
    },
    {
      "id": "S2",
      "tool": "read_sensors",
      "args": {"machine_id": "CURE-06", "sensor": "temp_c"},
      "purpose": "對照同管線 H2 6 號溫度。"
    },
    {
      "id": "S3",
      "tool": "read_sensors",
      "args": {"machine_id": "CURE-08", "sensor": "temp_c"},
      "purpose": "對照同管線 H2 8 號溫度。"
    },
    {
      "id": "S4",
      "tool": "cure_formula",
      "args": {
        "initial_temp": 128,
        "actual_temp": 122,
        "initial_time": 10,
        "total_time": 28,
        "activation_energy": 85
      },
      "purpose": "依等效硫化公式重算剩餘時間。"
    },
    {
      "id": "S5",
      "tool": "solve_schedule",
      "args": {"recalc": true, "machine": "CURE-07"},
      "purpose": "依新時間重新排程，計算人力缺口。"
    },
    {
      "id": "S6",
      "tool": "confirm_schedule",
      "args": {"approver": "supervisor", "action": "extend_or_reschedule"},
      "purpose": "主管核准延長或重排。"
    }
  ],
  "alert_card": {
    "title": "CURE-07 temp drop: 128→122°C",
    "summary": "預測穩定 122±1°C，中胎已硫化 10/28 h。同管線 6、8 號正常，疑似感測器漂移或單機洩漏。已重算剩餘時間並提交主管核准延長或重排。"
  }
}

R3_replan.text:
{
  "goal": "延長硫化時間並重排後續模次",
  "hypothesis": 
  {
    "id": "H1",
    "statement": "溫度下降至 122°C，反應速率約為正常值的 0.679 倍",
    "cause_code": "等效硫化公式",
    "expectation": 
    {
      "machine_id": "CURE-07",
      "channel": "temp_c",
      "op": ">=",
      "value": 121,
      "within_min": 30
    }
  },
  "steps": [
    {
      "id": "S1",
      "tool": "cure_formula",
      "args": {"total_h": 28, "done_h": 10, "T_actual": 122, "T_ref": 128},
      "purpose": "重算剩餘硫化時間與總時長（含延長時間）"
    },
    {
      "id": "S2",
      "tool": "solve_schedule",
      "args": {"replan": true, "size": "mid"},
      "purpose": "重排後續模次至可用機台（7~10 號共用），計算模／入模時段人力缺口"
    },
    {
      "id": "S3",
      "tool": "set_cure_time",
      "args": {"machine_id": "CURE-07", "new_total_h": "$S1.total_cure_h", "new_remain_h": "$S1.total_cure_h - 10"},
      "purpose": "設定新的建議硫化時間"
    },
    {
      "id": "S4",
      "tool": "notify_teams",
      "args": {"machine_id": "CURE-07", "reason": "硫化溫度下降，已重算時間並重排後續模次"},
      "purpose": "通知硫化機組、胎體組（夜班兼出入模）與生管"
    }
  ],
  "alert_card": {
    "title": "CURE-07 溫度下降處置",
    "summary": "溫度從 128°C 下降至 122°C，屬 SOP-CP-02 範圍。已重算總硫化 36.5 小時，延長 8.5 小時。已重排後續模次至 CURE-10、CURE-09、CURE-08（中胎共用機）。需主管核准新排程與時間設定。"
  }
}

